Read file /Users/ajeet/Projects/Hackathons/Sheridan Datathon 2026/src/components/weather/weather.css, lines 1-402
1: /* ==========================================================================
2:    Phase E3 weather surfaces, the --wx- token namespace
3:    (docs/research.md palette table, "New tokens live in a --wx- namespace
4:    next to --rp and --rv so the report and Money River files never change").
5: 
6:    Band vocabulary (src/lib/verdict.ts owns every band): the five verdict
7:    bands, Critical, Storm warning, Watch, Fair skies, and Clear, carry all
8:    color on these surfaces through their tailwind cp class and
9:    currentColor, so the badge and the strip share one source of band
10:    color (see the .wx-slot rule below). The seven state ladder from the
11:    E3 draft left with weatherState.ts, and its unused palette tokens were
12:    deleted with it.
13: 
14:    The one state accent kept is wx-storm #ff6a4d, storm vermillion, used
15:    only as a marker: the worst case continuation, the EI cliff line, and
16:    the storm tag. It never sets a band.
17: 
18:    Plus the two grounds every surface sits on: wx-grounds #070c18 (the
19:    archival navy, same value as --rp-void but read from its own token so
20:    this file never depends on --rp-) and wx-parchment #e9e0c9 for text.
21:    Parchment on wx-grounds stays above WCAG AA on every surface here.
22: 
23:    Motion in this file is gated behind prefers-reduced-motion:
24:    no-preference, matching src/index.css, which also zeroes animation
25:    durations globally under prefers-reduced-motion: reduce.
26:    ========================================================================== */
27: 
28: :root {
29:   /* The single state accent: marker only, never a band color. */
30:   --wx-storm: #ff6a4d;
31: 
32:   /* Grounds and text. */
33:   --wx-grounds: #070c18;
34:   --wx-parchment: #e9e0c9;
35:   --wx-rule: rgba(233, 224, 201, 0.24);
36:   --wx-text-dim: rgba(233, 224, 201, 0.74);
37:   --wx-text-faint: rgba(233, 224, 201, 0.54);
38: 
39:   /* Utility, deliberately local so nothing here reaches into --rp-. */
40:   --wx-font-display: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
41:     "Liberation Mono", monospace;
42:   --wx-font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
43:   --wx-radius: 4px;
44: }
45: 
46: /* ==========================================================================
47:    Forecast strip: 12 month tiles, one per verdict band
48:    ========================================================================== */
49: 
50: .wx-strip {
51:   display: block;
52:   width: 100%;
53: }
54: 
55: .wx-strip__svg {
56:   display: block;
57:   width: 100%;
58:   height: auto;
59: }
60: 
61: /* Band colored month slots: the verdict band's own tailwind class sets
62:    the color, fill picks it up through currentColor, and the 22 percent
63:    tint keeps the glyph and the curve legible on top. One source of
64:    band color for the badge and the strip (tailwind.config.js cp). */
65: .wx-slot {
66:   fill: currentColor;
67:   fill-opacity: 0.22;
68: }
69: 
70: .wx-strip__glyph {
71:   fill: currentColor;
72:   font-family: var(--wx-font-body);
73:   font-size: 13px;
74: }
75: 
76: .wx-strip__month {
77:   fill: var(--wx-parchment);
78:   font-family: var(--wx-font-display);
79:   font-size: 9.5px;
80:   letter-spacing: 0.06em;
81: }
82: 
83: .wx-strip__horizon {
84:   fill: var(--wx-text-faint);
85:   font-family: var(--wx-font-display);
86:   font-size: 10px;
87:   letter-spacing: 0.06em;
88: }
89: 
90: .wx-strip__empty {
91:   fill: var(--wx-parchment);
92:   font-family: var(--wx-font-display);
93:   font-size: 11px;
94: }
95: 
96: .wx-strip__placeholder {
97:   fill: none;
98:   stroke: var(--wx-rule);
99:   stroke-dasharray: 4 4;
100: }
101: 
102: /* Curve, grounds, and front ---------------------------------------------- */
103: 
104: .wx-zero-line {
105:   stroke: var(--wx-rule);
106:   stroke-width: 1;
107:   stroke-dasharray: 3 5;
108: }
109: 
110: .wx-history-line {
111:   fill: none;
112:   stroke: var(--wx-text-faint);
113:   stroke-width: 1.5;
114: }
115: 
116: .wx-history-dot {
117:   fill: var(--wx-text-faint);
118: }
119: 
120: .wx-history-legend {
121:   fill: var(--wx-text-faint);
122:   font-family: var(--wx-font-display);
123:   font-size: 9.5px;
124:   letter-spacing: 0.08em;
125: }
126: 
127: .wx-projection-line {
128:   fill: none;
129:   stroke: var(--wx-parchment);
130:   stroke-width: 2.5;
131:   stroke-linecap: round;
132:   stroke-linejoin: round;
133: }
134: 
135: /* The worst case continuation: dashed storm color so it never reads
136:    as the answer key figure on the solid projection line. */
137: .wx-continuation-line {
138:   fill: none;
139:   stroke: var(--wx-storm);
140:   stroke-width: 2;
141:   stroke-dasharray: 7 5;
142:   stroke-linecap: round;
143: }
144: 
145: .wx-front {
146:   stroke-width: 2;
147: }
148: 
149: .wx-front-active {
150:   stroke: var(--wx-storm);
151:   stroke-width: 2.5;
152: }
153: 
154: .wx-front-idle {
155:   stroke: var(--wx-rule);
156:   stroke-dasharray: 4 4;
157: }
158: 
159: /* Pins ------------------------------------------------------------------- */
160: 
161: .wx-pin-stem {
162:   stroke: var(--wx-parchment);
163:   stroke-width: 1.5;
164:   stroke-dasharray: 3 3;
165: }
166: 
167: .wx-pin-dot {
168:   fill: currentColor;
169:   stroke: var(--wx-grounds);
170:   stroke-width: 1.5;
171: }
172: 
173: .wx-pin__label {
174:   fill: var(--wx-parchment);
175:   font-family: var(--wx-font-display);
176:   font-size: 11px;
177:   font-weight: 700;
178:   letter-spacing: 0.04em;
179:   paint-order: stroke;
180:   stroke: var(--wx-grounds);
181:   stroke-width: 3px;
182:   stroke-linejoin: round;
183: }
184: 
185: .wx-pin__label-faint {
186:   fill: var(--wx-text-faint);
187:   font-size: 10px;
188:   font-weight: 400;
189: }
190: 
191: .wx-ei-pin {
192:   fill: var(--wx-storm);
193:   stroke: var(--wx-grounds);
194:   stroke-width: 1.5;
195: }
196: 
197: /* ==========================================================================
198:    Condition bands: the sky legend with the printed threshold sentence.
199:    One band vocabulary (src/lib/verdict.ts): the band's tailwind class on
200:    the list item sets the color, currentColor carries it into the left
201:    rule and the label, and the responsive grid keeps five bands readable
202:    from a phone up to a judging table.
203:    ========================================================================== */
204: 
205: .wx-bands {
206:   display: grid;
207:   grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
208:   gap: 6px;
209:   list-style: none;
210:   margin: 0;
211:   padding: 0;
212: }
213: 
214: .wx-band {
215:   display: flex;
216:   align-items: baseline;
217:   gap: 10px;
218:   padding: 8px 12px;
219:   background: rgba(233, 224, 201, 0.05);
220:   border: 1px solid var(--wx-rule);
221:   border-left: 6px solid currentColor;
222:   border-radius: var(--wx-radius);
223:   min-height: 44px;
224: }
225: 
226: .wx-band-active {
227:   box-shadow: inset 0 0 0 2px var(--wx-parchment);
228: }
229: 
230: .wx-band__glyph {
231:   font-size: 1rem;
232:   color: var(--wx-parchment);
233: }
234: 
235: .wx-band__body {
236:   display: flex;
237:   flex-wrap: wrap;
238:   align-items: baseline;
239:   gap: 2px 12px;
240:   min-width: 0;
241: }
242: 
243: .wx-band__label {
244:   font-family: var(--wx-font-display);
245:   font-size: 0.8125rem;
246:   letter-spacing: 0.08em;
247:   text-transform: uppercase;
248:   color: currentColor;
249: }
250: 
251: .wx-band__threshold {
252:   font-family: var(--wx-font-body);
253:   font-size: 0.8125rem;
254:   color: var(--wx-text-dim);
255: }
256: 
257: /* ==========================================================================
258:    EI cliff overlay: a marker line that sits over the forecast strip, plus
259:    a dotted second line for the worst case pin. The wiring view wraps the
260:    strip and this overlay in .wx-cliff-wrap, which is the positioning
261:    context; the overlay's own .wx-cliff-set fills that box and the lines
262:     position against it with the slot percent the strip's stripLayout
263:     shares, so the marker lands on the same x the curve uses.
264:    ========================================================================== */
265: 
266: .wx-cliff-wrap {
267:   position: relative;
268: }
269: 
270: .wx-cliff-set {
271:   position: absolute;
272:   inset: 0;
273:   pointer-events: none;
274:   z-index: 2;
275: }
276: 
277: .wx-cliff {
278:   position: absolute;
279:   top: 0;
280:   bottom: 0;
281:   width: 0;
282:   border-left: 2px dashed var(--wx-storm);
283: }
284: 
285: /* The worst case continuation line: dotted and dimmer, so it never
286:    reads as the answer key marker or the solid projection curve. */
287: .wx-cliff-after {
288:   border-left-style: dotted;
289:   opacity: 0.7;
290: }
291: 
292: .wx-cliff__label {
293:   position: absolute;
294:   top: 3px;
295:   left: 0;
296:   white-space: nowrap;
297:   padding: 1px 6px;
298:   border-radius: 2px;
299:   background: var(--wx-storm);
300:   color: var(--wx-grounds);
301:   font-family: var(--wx-font-display);
302:   font-size: 0.625rem;
303:   font-weight: 700;
304:   letter-spacing: 0.1em;
305:   text-transform: uppercase;
306: }
307: 
308: /* On a phone the label is wider than the gap to the strip edge, so it
309:    wraps instead of overflowing the panel. */
310: @media (max-width: 40rem) {
311:   .wx-cliff__label {
312:     white-space: normal;
313:     max-width: 62vw;
314:   }
315: }
316: 
317: /* ==========================================================================
318:    Weather panel: the full width section that composes the strip, the
319:    cliff overlay, the honesty note, and the band key. Local spacing only,
320:    nothing here reaches into the cp or rp namespaces beyond the panel
321:    classes the console already defines.
322:    ========================================================================== */
323: 
324: .wx-panel {
325:   display: flex;
326:   flex-direction: column;
327:   gap: 12px;
328: }
329: 
330: .wx-storm-tag {
331:   display: inline-block;
332:   margin-right: 8px;
333:   padding: 1px 6px;
334:   border: 1px solid var(--wx-storm);
335:   border-radius: 2px;
336:   font-family: var(--wx-font-display);
337:   font-size: 0.625rem;
338:   font-weight: 700;
339:   letter-spacing: 0.1em;
340:   text-transform: uppercase;
341:   color: var(--wx-storm);
342:   vertical-align: 1px;
343: }
344: 
345: .wx-honesty {
346:   display: flex;
347:   flex-wrap: wrap;
348:   align-items: baseline;
349:   gap: 4px 10px;
350:   margin: 0;
351:   font-family: var(--wx-font-body);
352:   font-size: 0.8125rem;
353:   line-height: 1.5;
354:   color: var(--wx-text-dim);
355: }
356: 
357: .wx-honesty__swatch {
358:   align-self: center;
359:   width: 22px;
360:   height: 0;
361:   border-top: 2px solid var(--wx-text-faint);
362: }
363: 
364: .wx-honesty__legend {
365:   font-family: var(--wx-font-display);
366:   font-size: 0.6875rem;
367:   letter-spacing: 0.08em;
368:   text-transform: uppercase;
369:   color: var(--wx-text-faint);
370: }
371: 
372: .wx-bands__title {
373:   margin: 4px 0 0;
374: }
375: 
376: /* ==========================================================================
377:    Motion: strip tiles settle in, the cliff line draws down. Only when
378:    motion is welcome; the global prefers-reduced-motion: reduce block in
379:    src/index.css zeroes every animation duration as well.
380:    ========================================================================== */
381: 
382: @media (prefers-reduced-motion: no-preference) {
383:   .wx-strip__tile {
384:     animation: wx-fade 380ms ease-out backwards;
385:     /* The per tile stagger arrives as an inline animation-delay from
386:        ForecastStrip, which wins over this class shorthand. */
387:   }
388: 
389:   .wx-cliff {
390:     animation: wx-fade 480ms ease-out backwards;
391:   }
392: }
393: 
394: @keyframes wx-fade {
395:   from {
396:     opacity: 0;
397:   }
398: 
399:   to {
400:     opacity: 1;
401:   }
402: }

Read file /Users/ajeet/Projects/Hackathons/Sheridan Datathon 2026/src/components/atlas/atlas.css, lines 1-597
1: /* ==========================================================================
2:    Phase E5 Storm Atlas (ax): the population panel and its strip plot.
3: 
4:    Band hue never arrives as a literal in this file. Every element that
5:    colors itself carries a data-band attribute read straight from the
6:    verdict vocabulary, and the five mapping rules below resolve it
7:    against the --cp-band tokens in src/index.css, so the atlas, the
8:    console badge, and the forecast strip stay one palette with one
9:    source of truth.
10: 
11:    Nothing here animates. The field re-counts itself on every twist,
12:    and a population that changes must not also move on its own; the
13:    only motion this phase owns is the scroll into the console, which
14:    steps instead of glides under prefers-reduced-motion.
15:    ========================================================================== */
16: 
17: .ax-shell {
18:   display: grid;
19:   gap: var(--rp-s4);
20:   background: var(--cp-surface);
21:   border: 1px solid var(--cp-rule);
22:   border-radius: var(--cp-radius);
23:   padding: var(--rp-s5);
24:   min-width: 0;
25: }
26: 
27: /* Headline panel ---------------------------------------------------------- */
28: 
29: .ax-atlas {
30:   display: flex;
31:   flex-direction: column;
32:   gap: var(--rp-s3);
33:   min-width: 0;
34: }
35: 
36: .ax-headline {
37:   margin: 0;
38:   font-family: var(--rp-font-display);
39:   font-weight: 700;
40:   font-size: clamp(1.625rem, 3.4vw, 2.375rem);
41:   line-height: 1.2;
42:   color: var(--cp-ink);
43:   overflow-wrap: anywhere;
44: }
45: 
46: .ax-subline {
47:   display: flex;
48:   flex-wrap: wrap;
49:   align-items: baseline;
50:   gap: var(--rp-s2) var(--rp-s4);
51:   margin: 0;
52:   font-family: var(--rp-font-utility);
53:   font-size: 0.8125rem;
54:   font-variant-numeric: tabular-nums;
55:   color: var(--cp-ink-dim);
56: }
57: 
58: .ax-subline__count {
59:   color: var(--cp-ink);
60:   font-weight: 600;
61: }
62: 
63: .ax-compare {
64:   color: var(--rp-verified);
65: }
66: 
67: .ax-track {
68:   padding: 2px var(--rp-s3);
69:   border: 1px solid var(--cp-rule);
70:   border-radius: 999px;
71:   color: var(--cp-ink-faint);
72: }
73: 
74: /* Band cells: glyph, label, count, percent, all on one hue --------------- */
75: 
76: .ax-cells {
77:   display: grid;
78:   grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr));
79:   gap: var(--rp-s2);
80:   list-style: none;
81:   margin: 0;
82:   padding: 0;
83: }
84: 
85: .ax-cell {
86:   --ax-band: var(--cp-ink-faint);
87:   display: grid;
88:   grid-template-columns: auto minmax(0, 1fr);
89:   gap: 2px var(--rp-s2);
90:   align-content: start;
91:   min-height: 44px;
92:   padding: var(--rp-s3);
93:   background: var(--cp-inset);
94:   border: 1px solid var(--cp-rule);
95:   border-top: 4px solid var(--ax-band);
96:   border-radius: var(--cp-radius);
97: }
98: 
99: .ax-cell__glyph {
100:   color: var(--ax-band);
101:   font-size: 1.125rem;
102:   line-height: 1.2;
103: }
104: 
105: .ax-cell__label {
106:   font-family: var(--rp-font-utility);
107:   font-size: 0.6875rem;
108:   font-weight: 600;
109:   letter-spacing: 0.1em;
110:   text-transform: uppercase;
111:   color: var(--cp-ink-dim);
112: }
113: 
114: .ax-cell__count {
115:   grid-column: 1 / -1;
116:   font-family: var(--rp-font-display);
117:   font-weight: 700;
118:   font-size: 1.375rem;
119:   line-height: 1.1;
120:   font-variant-numeric: tabular-nums;
121:   color: var(--ax-band);
122: }
123: 
124: .ax-cell__percent {
125:   grid-column: 1 / -1;
126:   font-size: 0.75rem;
127:   font-variant-numeric: tabular-nums;
128:   color: var(--cp-ink-faint);
129: }
130: 
131: /* One mapping rule per band, scoped to the shell -------------------------- */
132: 
133: .ax-shell [data-band='critical'] {
134:   --ax-band: var(--cp-band-critical);
135: }
136: 
137: .ax-shell [data-band='storm_warning'] {
138:   --ax-band: var(--cp-band-storm);
139: }
140: 
141: .ax-shell [data-band='watch'] {
142:   --ax-band: var(--cp-band-watch);
143: }
144: 
145: .ax-shell [data-band='fair_skies'] {
146:   --ax-band: var(--cp-band-fair);
147: }
148: 
149: .ax-shell [data-band='clear'] {
150:   --ax-band: var(--cp-band-clear);
151: }
152: 
153: /* Strip plot -------------------------------------------------------------- */
154: 
155: .ax-figure {
156:   display: grid;
157:   gap: var(--rp-s2);
158:   margin: 0;
159:   min-width: 0;
160: }
161: 
162: .ax-plot__svg {
163:   display: block;
164:   width: 100%;
165:   height: auto;
166: }
167: 
168: .ax-seg {
169:   --ax-band: var(--cp-ink-faint);
170:   fill: var(--ax-band);
171:   opacity: 0.09;
172: }
173: 
174: .ax-bar {
175:   --ax-band: var(--cp-ink-faint);
176:   fill: var(--ax-band);
177:   opacity: 0.4;
178: }
179: 
180: .ax-dot {
181:   --ax-band: var(--cp-ink-faint);
182:   fill: var(--ax-band);
183:   opacity: 0.75;
184: }
185: 
186: .ax-axis {
187:   stroke: var(--cp-rule);
188:   stroke-width: 1;
189: }
190: 
191: .ax-tick,
192: .ax-unit {
193:   font-family: var(--rp-font-utility);
194:   font-size: 14px;
195:   fill: var(--cp-ink-faint);
196: }
197: 
198: .ax-unit {
199:   font-size: 13px;
200: }
201: 
202: .ax-ring {
203:   fill: none;
204:   stroke: var(--rp-paper);
205:   stroke-width: 1.5;
206: }
207: 
208: .ax-ring__label {
209:   font-family: var(--rp-font-utility);
210:   font-size: 13px;
211:   font-weight: 600;
212:   fill: var(--rp-paper);
213:   text-anchor: middle;
214: }
215: 
216: .ax-caption {
217:   font-family: var(--rp-font-body);
218:   font-size: 0.75rem;
219:   line-height: 1.5;
220:   color: var(--cp-ink-faint);
221: }
222: 
223: /* Loading and failure notes ------------------------------------------------ */
224: 
225: .ax-note {
226:   margin: 0;
227:   font-family: var(--rp-font-body);
228:   font-size: 0.875rem;
229:   line-height: 1.55;
230:   color: var(--cp-ink-dim);
231:   max-width: 60ch;
232: }
233: 
234: /* ==========================================================================
235:    District cartogram and rain gauge (E5 extension).
236: 
237:    The header at the top of this file said nothing animates, which was
238:    true until this block. The two motions below are the cascade
239:    moment: a twist lands and every tile shade plus the gauge fill step
240:    together over 600ms ease-out, and both live only inside
241:    prefers-reduced-motion: no-preference, so a judge who asked for
242:    reduced motion gets an instant swap (the global reduce block in
243:    src/index.css zeroes durations again as a second gate). Band hue
244:    still never arrives as a literal: the five mapping rules repeat at
245:    the end of this block so each new component resolves its band color
246:    even when mounted outside the atlas shell.
247:    ========================================================================== */
248: 
249: /* Headline row: the panel, then the gauge beside it ---------------- */
250: 
251: .ax-lead {
252:   display: grid;
253:   grid-template-columns: minmax(0, 1fr);
254:   gap: var(--rp-s4);
255:   align-items: start;
256:   min-width: 0;
257: }
258: 
259: @media (min-width: 760px) {
260:   .ax-lead {
261:     grid-template-columns: minmax(0, 1fr) auto;
262:   }
