input.newString:
/* ==========================================================================
   Report tokens: a pixel game weather station read in daylight. Six named
   colors, three type roles, one spacing scale. No external fonts, so the
   booth machine never reaches the network. The values run light: a pale
   sky tinted ground, white panel cards, dark slate ink, and the five
   verdict band hues re-tuned so every band label clears WCAG AA on both
   the ground and a panel.
   ========================================================================== */

:root {
  /* Palette (named hex values, the whole report runs on these six). */
  --rp-void: #eaf1fb; /* daylight ground, pale sky paper */
  --rp-paper: #16273f; /* slate ink, every piece of primary text */
  --rp-rule: #8496b3; /* blueprint rule on light */
  --rp-verified: #0a7a5a; /* provenance teal, locked and checked */
  --rp-money: #8f5502; /* ledger amber, discretionary dollars */
  --rp-stamp: #c02f12; /* audit stamp red, warnings and mismatches */

  /* Derived tones (solid over the daylight ground, so contrast holds). */
  --rp-panel: #ffffff;
  --rp-panel-strong: #f2f7fd;
  --rp-text-dim: #3f5270;
  --rp-text-faint: #56688a;
  --rp-verified-dim: rgba(10, 122, 90, 0.55);
  --rp-verified-ghost: rgba(10, 122, 90, 0.1);
  --rp-money-dim: rgba(143, 85, 2, 0.55);
  --rp-money-ghost: rgba(143, 85, 2, 0.1);
  --rp-stamp-ghost: rgba(192, 47, 18, 0.1);
  --rp-gridline: rgba(132, 150, 179, 0.3);

