input.newString:
/* ==========================================================================
   Console tokens and surfaces (cp): the E2 instrument panel.
   Reuses the rp palette as custom properties, adds one hue per verdict
   band (mirrored in tailwind.config.js as text-cp-* utilities), and keeps
   every interactive target at 44px or taller. Band text color comes from
   the band's tailwind class, never from these rules, so the badge and the
   forecast strip in E3 share one source of color. The ground is daylight
   now: panels are white cards, the inset is a pale sky tint, and each
   band hue is dark enough to read as text on both.
   ========================================================================== */

:root {
  --cp-surface: var(--rp-panel);
  --cp-surface-strong: var(--rp-panel-strong);
  --cp-rule: var(--rp-rule);
  --cp-ink: var(--rp-paper);
  --cp-ink-dim: var(--rp-text-dim);
  --cp-ink-faint: var(--rp-text-faint);
  --cp-inset: #e6edf8;
  /* Hard offset shadow color for the chunky 8 bit chrome: one flat
     value, no blur, so every panel reads as a raised pixel tile. */
  --cp-shadow: #c3d3ea;
  --cp-shadow-strong: #9db2d0;

  --cp-band-critical: #c02f12;
  --cp-band-storm: #8f5502;
  --cp-band-watch: #5744c2;
  --cp-band-fair: #0b6b93;
  --cp-band-clear: #0a7a5a;

  --cp-radius: var(--rp-radius);
}

