/* ==========================================================================
   District map: one path per district, drawn where it sits in Czechia.
   The outlines come from bundled geometry (src/assets), so this block
   never waits on a network call. A path without a band takes no shade
   at all, which is how an absent split stays visibly absent instead of
   reading as a safe zero, and the hatch rides on top of the shade as a
   second path so an incomplete source row keeps its colour and its
   counts together. Motion mirrors the tiles: the shade steps in over
   600ms only inside prefers-reduced-motion: no-preference.
   ========================================================================== */

.ax-map {
  display: block;
  width: 100%;
  height: auto;
  background: var(--cp-inset);
  border: 2px solid var(--cp-ink);
}

.ax-map__path {
  --ax-band: var(--cp-ink-faint);
  fill: var(--cp-surface);
  stroke: var(--cp-ink);
  stroke-width: 1.5;
  stroke-linejoin: round;
  cursor: pointer;
}

.ax-map__path[data-band] {
  fill: color-mix(in srgb, var(--ax-band) 32%, var(--cp-surface));
}

.ax-map__hatch {
  fill: url(#ax-no-data-hatch);
  stroke: none;
  pointer-events: none;
}

.ax-map__path:hover {
  fill: var(--ax-band);
}

.ax-map__path:focus-visible {
  fill: var(--ax-band);
  stroke-width: 4;
  outline: 3px solid var(--rp-paper);
  outline-offset: 1px;
}

@media (prefers-reduced-motion: no-preference) {
  .ax-map__path {
    transition:
      fill 600ms ease-out,
      stroke-width 200ms ease-out;
  }
}
EOF
